import { addEntry } from "../../store.js";

export const POST = Run.POST(async (context) => {
  const form = await context.request.formData();
  const message = String(form.get("message") || "").trim();

  if (message) {
    addEntry(message);
  }

  return context.redirect("/guestbook", 303);
});

